"""Verify independent site and equipment sources before Native lamp capture."""

import hashlib
import json
from pathlib import Path

from lamp_direction import CASES, validate_scene


ASSIGNMENT = 'testing__C230294__NRS-484D-100-1__motor_vehicle_driver'
SOURCE_FIELDS = ('map_sha256', 'jurisdiction', 'highway', 'vehicle_class', 'parking_status',
                 'required_lamp_provisions', 'device_authority',
                 'device_geometry', 'device_message', 'device_timing',
                 'route', 'sunset_sunrise', 'clock', 'visibility')


def digest(data):
    return hashlib.sha256(data).hexdigest()


def verify(packet_path, case_name):
    """Require a distinct, hash-bound original source for every scene assertion.

    The packet is an operator review artifact, not a legal finding. A file can
    establish a provenance link; a later human audit still checks its truth.
    """
    if case_name not in {case.name for case in CASES}:
        raise ValueError('unknown exact lamp case')
    packet_path = Path(packet_path).resolve()
    packet = json.loads(packet_path.read_text())
    if packet.get('case_id') != ASSIGNMENT + '__' + case_name:
        raise ValueError('lamp source packet case mismatch')
    scene = packet.get('scene')
    if not isinstance(scene, dict):
        raise ValueError('lamp source packet scene missing')
    sources = packet.get('sources')
    if not isinstance(sources, dict) or set(sources) != set(SOURCE_FIELDS):
        raise ValueError('complete lamp source inventory missing')
    root = packet_path.parent
    for field in SOURCE_FIELDS:
        entry = sources[field]
        if not isinstance(entry, dict) or not isinstance(entry.get('path'), str):
            raise ValueError('lamp source entry missing: ' + field)
        path = (root / entry['path']).resolve()
        if not path.is_relative_to(root) or not path.is_file():
            raise ValueError('lamp source file missing: ' + field)
        data = path.read_bytes()
        expected = entry.get('sha256')
        if not isinstance(expected, str) or digest(data) != expected:
            raise ValueError('lamp source bytes changed: ' + field)
        document = json.loads(data)
        if not isinstance(document, dict) or field not in document:
            raise ValueError('lamp source assertion missing: ' + field)
        if scene.get(field) is None:
            raise ValueError('lamp scene assertion missing: ' + field)
        if document[field] != scene.get(field):
            raise ValueError('lamp scene differs from source: ' + field)
        if scene.get(field + '_source_sha256') != expected:
            raise ValueError('lamp scene source seal differs: ' + field)
    case = next(case for case in CASES if case.name == case_name)
    validate_scene(scene, case)
    return {'packet': packet, 'case': case,
            'packet_sha256': digest(packet_path.read_bytes()),
            'source_sha256': {field: sources[field]['sha256'] for field in SOURCE_FIELDS}}

"""Saved-only source-bound lamp measurements; no legal conclusion."""

import argparse
import hashlib
import json
from pathlib import Path

from lamp_direction import require
from saved_audit import audit_saved


SOURCES = ('lamp-context-packet.json', 'original-lamp-ticks.jsonl',
           'camera-source-manifest.json')


def source_hashes(attempt):
    bound = {}
    for name in SOURCES:
        path = Path(attempt) / name
        require(path.is_file(), 'Missing required source: ' + name)
        bound[name] = hashlib.sha256(path.read_bytes()).hexdigest()
    return bound


def measure_vehicle_context(report, sources):
    return {'value': {'frame_count': report['frame_count'],
                      'map_sha256': report['map_sha256'],
                      'vehicle_class_source_sha256': report['vehicle_class_source_sha256']},
            'method': 'measure_vehicle_context', 'sources': sources}


def measure_device_direction(report, sources):
    return {'value': {'directs_lamps': report['device_directs'],
                      'source_packet_sha256': report['source_packet_sha256'],
                      'route_source_sha256': report['route_source_sha256']},
            'method': 'measure_device_direction', 'sources': sources}


def measure_required_lamps(report, sources):
    return {'value': {'on_frame_counts': report['lamp_on_frame_counts'],
                      'provisions_source_sha256': report['required_lamp_provisions_source_sha256']},
            'method': 'measure_required_lamps', 'sources': sources}


def measure_time_visibility(report, sources):
    return {'value': report['statutory_context'],
            'method': 'measure_time_visibility', 'sources': sources}


def finalize(attempt, case_name):
    attempt = Path(attempt).resolve()
    sources = source_hashes(attempt)
    audit = audit_saved(attempt, case_name)
    report = json.loads((attempt / 'lamp-measurement.json').read_text())
    measurements = {
        'vehicle_context': measure_vehicle_context(report, sources),
        'device_direction': measure_device_direction(report, sources),
        'required_lamp_states': measure_required_lamps(report, sources),
        'time_visibility_context': measure_time_visibility(report, sources),
    }
    return {'format': 'worker-analysis-report', 'case_id': audit['case_id'],
            'measurements': measurements,
            'original_source_audit': audit, 'legal_verdict': None,
            'physical_acceptance_claimed': False,
            'limitations': ['Original device face, actual emitted light and legal sufficiency require independent local review.']}


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--attempt', required=True)
    parser.add_argument('--output', required=True)
    args = parser.parse_args()
    config = json.loads((Path(args.attempt) / 'config.json').read_text())
    case_name = config['selected_case_id'].rsplit('__', 1)[-1]
    report = finalize(args.attempt, case_name)
    Path(args.output).write_text(json.dumps(report, indent=2) + '\n')
    if (Path(args.attempt) / 'capture' / 'manifest.json').is_file():
        from native_publication import publish
        from worker_exchange.native_output import write_result
        write_result(args.attempt, publish(args.attempt, report))


if __name__ == '__main__':
    main()
